<script setup>
import { reactive, ref } from 'vue'
import { Delete, Edit, Plus } from '@element-plus/icons-vue'
const dialog=ref(false);const form=reactive({id:null,categoryName:'',categoryAlias:''});const rows=ref([{id:1,categoryName:'前端开发',categoryAlias:'frontend',time:'2026-08-20'},{id:2,categoryName:'后端开发',categoryAlias:'backend',time:'2026-08-19'},{id:3,categoryName:'生活随笔',categoryAlias:'life',time:'2026-08-17'}])
function add(){Object.assign(form,{id:null,categoryName:'',categoryAlias:''});dialog.value=true}function edit(r){Object.assign(form,r);dialog.value=true}function del(r){rows.value=rows.value.filter(x=>x.id!==r.id)}function save(){if(form.id){Object.assign(rows.value.find(x=>x.id===form.id),form)}else rows.value.unshift({...form,id:Date.now(),time:new Date().toLocaleDateString()});dialog.value=false}
</script>
<template><section class="page-panel glass"><div class="page-heading"><div><h2>分类管理</h2><p>为文章维护清晰的分类体系</p></div><el-button type="primary" :icon="Plus" @click="add">新增分类</el-button></div><div class="table-wrap"><el-table :data="rows"><el-table-column prop="categoryName" label="分类名称" min-width="170"/><el-table-column prop="categoryAlias" label="分类别名" min-width="160"/><el-table-column prop="time" label="更新时间" width="150"/><el-table-column label="操作" width="130"><template #default="{row}"><el-button text :icon="Edit" @click="edit(row)">编辑</el-button><el-button text type="danger" :icon="Delete" @click="del(row)">删除</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" :title="form.id?'编辑分类':'新增分类'" width="440px"><el-form label-width="75px"><el-form-item label="分类名称"><el-input v-model="form.categoryName"/></el-form-item><el-form-item label="分类别名"><el-input v-model="form.categoryAlias"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template>
